import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Usf Panel: Tunnels vs. Censorship","description":"Building proxy panels for an environment where blocking is an arms race — the story and philosophy behind Usf Panel and its family.","frontmatter":{"title":"Usf Panel: Tunnels vs. Censorship","description":"Building proxy panels for an environment where blocking is an arms race — the story and philosophy behind Usf Panel and its family."},"headers":[],"relativePath":"en/vibe-stories/story-3/index.md","filePath":"en/vibe-stories/story-3/index.md"}`),a={name:`en/vibe-stories/story-3/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="usf-panel-tunnels-vs-censorship" tabindex="-1">Usf Panel: Tunnels vs. Censorship <a class="header-anchor" href="#usf-panel-tunnels-vs-censorship" aria-label="Permalink to “Usf Panel: Tunnels vs. Censorship”">​</a></h1><p>Some software is a convenience; some is a lifeline. My panel family — <strong>Usf Panel</strong>, usf-edge, edge-pp, Render-usf — belongs to the second kind. They manage VLESS tunnels and subscriptions for people whose internet is routinely filtered, including mine.</p><h2 id="the-threat-model-is-real" tabindex="-1">The threat model is real <a class="header-anchor" href="#the-threat-model-is-real" aria-label="Permalink to “The threat model is real”">​</a></h2><p>Building for censored networks changes every design decision. Platforms themselves become attack surfaces: when one provider starts mass-banning proxy workloads, your users go dark — so every panel I ship deploys to <strong>five platforms with one command</strong>, and edge variants keep state in Cloudflare KV across 300+ PoPs where there is no server to seize.</p><h2 id="engineering-under-fire" tabindex="-1">Engineering under fire <a class="header-anchor" href="#engineering-under-fire" aria-label="Permalink to “Engineering under fire”">​</a></h2><ul><li><strong>Subscription links</strong> must regenerate cleanly across Clash, v2ray and sing-box — one broken format means one stranded user.</li><li><strong>Multi-user quotas</strong> keep one heavy user from exposing everyone.</li><li><strong>Admin hardening</strong> — token + 2FA — because the panel itself is the juiciest target.</li><li><strong>Migration drills</strong> — I practice platform-to-platform moves before I need them, not during an outage.</li></ul><p>The full design philosophy is in the <a href="/Usf/en/about/networking/">networking section</a>; the flagship&#39;s details are in <a href="/Usf/en/projects/usf-panel/">Usf Panel</a>. What the story boils down to: treat access to information as critical infrastructure, and engineer it with that respect.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};